            return "ok"

    client = MockClient()
    result = fetch(client, "http://test.com")
    assert result == "ok"

if __name__ == "__main__":
    test_timeout_parameter()
    test_exception_propagation()
    test_arguments_preserved()
    print("All tests passed!")
